const requireOps=()=>{if(!ops())throw Error('Switch to BHD Operations for this action.');};
const xnumber=(value,min=0,max=1000000)=>{const n=Number(value);if(!Number.isFinite(n)||n<min||n>max)throw Error('Enter a valid amount or quantity.');return n;};
const xtext=(value,max=500)=>{const t=String(value||'').trim();if(!t)throw Error('Complete all required fields.');return t.slice(0,max);};
const xint=(value,min=1,max=1000)=>{const n=xnumber(value,min,max);if(!Number.isInteger(n))throw Error('Use a whole pallet quantity.');return n;};
function auditExchange(action,reference,detailText){ex().audit.unshift({id:uid('E-'),time:new Date().toISOString(),actor:roleLabel(),action,reference,detail:detailText});}
function xform(kind,body,id='',label='Save'){return `<form data-exchange-form="${kind}" data-id="${esc(id)}"><div class="error" role="alert"></div>${body}<button class="btn primary full" type="submit">${label}</button></form>`;}
function xtabs(kind,selected,choices){return `<div class="exchange-tabs" role="group" aria-label="${esc(kind)} views">${choices.map(([v,l])=>`<button class="tab ${selected===v?'active':''}" data-action="x-view" data-id="${kind}|${v}" aria-pressed="${selected===v}">${l}</button>`).join('')}</div>`;}
function demoReview(p){return badge(p?.status==='Reviewed'?'Reviewed · demo':'Review pending',p?.status==='Reviewed'?'teal':'amber');}
function distanceMiles(a,b){if(!exchangeCities[a]||!exchangeCities[b])return null;const [lat1,lon1]=exchangeCities[a].map(n=>n*Math.PI/180),[lat2,lon2]=exchangeCities[b].map(n=>n*Math.PI/180);const h=Math.sin((lat2-lat1)/2)**2+Math.cos(lat1)*Math.cos(lat2)*Math.sin((lon2-lon1)/2)**2;return Math.round(3959*2*Math.asin(Math.min(1,Math.sqrt(h))));}
function shelfDays(f){const m=f.shelf.match(/(?:Use by|Best before)\s+(.+)/i);const t=Date.parse(f.expiry||m?.[1]||'');return Number.isFinite(t)?Math.floor((t-Date.parse(demoDate))/86400000):null;}
function needMatches(n){
 if(!n.active)return [];
 const p=partnerNamed(n.bank);if(!p||p.status!=='Reviewed'||!p.temperatures.includes(n.temp))return [];
 return state.items.filter(f=>['Donation','For sale','Shared order'].includes(f.type)&&openFood(f)).map(f=>{
  const distance=distanceMiles(n.city,f.city),remaining=Math.max(0,f.pallets-held(f)),days=shelfDays(f),words=n.keywords.toLowerCase().split(',').map(w=>w.trim()).filter(Boolean);
  const text=(f.title+' '+f.product).toLowerCase(),quantity=Math.min(remaining,n.quantity,p.pallets);
  if(!words.some(w=>text.includes(w))||f.temp!==n.temp||distance===null||distance>n.radius||quantity<1||(!n.partial&&quantity<n.quantity)||(days!==null&&days<n.minDays))return null;
  return {needId:n.id,itemId:f.id,distance,quantity,days,review:days===null?'Confirm shelf life and receiving appointment':'Confirm pickup and receiving appointments'};
 }).filter(Boolean).sort((a,b)=>a.distance-b.distance||b.quantity-a.quantity);
}
function scanNeeds(){let added=0;for(const n of ex().needs)for(const m of needMatches(n)){const key=n.id+'|'+m.itemId;if(ex().seen.includes(key))continue;ex().seen.push(key);ex().alerts.unshift({id:uid('A-'),...m,bank:n.bank,read:false});state.notifications.unshift('Food match for '+n.bank+': '+item(m.itemId).product);added++;}state.notifications=state.notifications.slice(0,30);if(added)save();return added;}
function addNeed(v){const p=partnerNamed(v.bank);if(state.role==='bank'&&v.bank!==state.bank)throw Error('Post needs for your selected food bank.');if(!p)throw Error('Choose a network food bank.');if(!exchangeCities[v.city])throw Error('Choose a supported demo city.');const n={id:uid('N-'),bank:v.bank,keywords:xtext(v.keywords,150),city:v.city,radius:xnumber(v.radius,1,1000),quantity:xint(v.quantity),temp:v.temp,minDays:xint(v.minDays,0,730),frequency:v.frequency,day:v.day,hours:xtext(v.hours,80),partial:!!v.partial,active:true};if(!p.temperatures.includes(n.temp))throw Error('This food bank is not equipped for that temperature.');ex().needs.push(n);auditExchange('Need created',n.id,n.keywords);return n;}
function matchPage(){const needs=ex().needs.filter(n=>state.role!=='bank'||n.bank===state.bank),matches=needs.flatMap(n=>needMatches(n).map(m=>({...m,need:n})));return head('','Matches & standing needs','Tell the network what you need. Compatible food appears here as offers change.',btn('Post a standing need','x-need','primary'))+
 `<div class="note blue">Matches use product keywords, approximate distance, available quantity, storage capability, and shelf life. Receiving hours stay visible for appointment review. Alerts are in-app demo notifications; no email or SMS is sent.</div><div class="exchange-summary"><div><strong>${matches.length}</strong>current matches</div><div><strong>${needs.filter(n=>n.active).length}</strong>active needs</div><div><strong>${ex().alerts.filter(a=>!a.read&&(state.role!=='bank'||a.bank===state.bank)).length}</strong>unread match alerts</div></div><div class="section-head"><h2>Food that fits</h2>${btn('Mark match alerts read','x-alerts-read','')}</div><div class="exchange-grid">${matches.map(m=>{const f=item(m.itemId);return `<article class="card x-card">${badge(f.type,'gray')}<h3>${esc(f.product)}</h3><p>${esc(m.need.bank)} · ${m.quantity} pallets available to match</p><div class="x-facts"><span>${m.distance} mi approximate</span><span>${esc(f.temp)}</span><span>${m.days===null?'Shelf life: review':m.days+' days shelf life'}</span></div><p class="small muted">${esc(f.city)} → ${esc(m.need.city)}<br>Receiving: ${esc(m.need.day)} · ${esc(m.need.hours)}</p><div class="note">${m.review}. A match does not reserve stock.</div><div class="row wrap">${btn('Review food','food','primary',f.id)}${btn('Compare delivered cost','x-cost','',f.id)}</div></article>`;}).join('')||'<div class="empty">No compatible offers yet. Your active needs will be checked as listings change.</div>'}</div><h2 class="sec-h">Your standing needs</h2><div class="card table-wrap"><table><thead><tr><th>Need</th><th>Receiving</th><th>Schedule</th><th>Status</th><th></th></tr></thead><tbody>${needs.map(n=>`<tr><td><strong>${esc(n.keywords)}</strong><small>${esc(n.bank)} · ${n.quantity} pallets · ${n.radius} mi radius</small></td><td>${esc(n.temp)}<small>${esc(n.hours)} · ${n.minDays}+ shelf-life days</small></td><td>${esc(n.frequency)}<small>${esc(n.day)}</small></td><td>${badge(n.active?'Active':'Paused',n.active?'teal':'gray')}</td><td>${btn(n.active?'Pause':'Resume','x-need-toggle','sm',n.id)}</td></tr>`).join('')}</tbody></table></div>`;}
function needDialog(){dialog('Post a standing need',xform('need',`<div class="form-grid">${select('bank','Food bank',ex().partners.filter(p=>p.kind==='Food bank').map(p=>p.name),state.bank)}${field('keywords','Products / keywords, separated by commas','text','','required placeholder="beans, rice, protein"')}${select('city','Receiving city',Object.keys(exchangeCities),'Dayton, OH')}${field('radius','Search radius (approximate miles)','number',200,'required min="1" max="1000"')}${field('quantity','Pallets needed','number',3,'required min="1" step="1"')}${select('temp','Storage temperature',['Ambient','Refrigerated','Frozen'])}${field('minDays','Minimum shelf life (days)','number',7,'required min="0" step="1"')}${select('frequency','Frequency',['One time','Weekly','Monthly'])}${select('day','Preferred receiving day',['Monday','Tuesday','Wednesday','Thursday','Friday'])}${field('hours','Receiving hours','text','08:00-15:00','required')}</div><label class="check"><input type="checkbox" name="partial" checked> Accept partial quantities.</label><p class="small muted">Recurring needs keep matching; they do not book recurring shipments.</p>`,'','Save need & find matches'),'AUTOMATIC MATCHING',true);}
function poolQuantity(p){return p.joins.reduce((n,j)=>n+j.quantity,0);}
function poolCosts(p){const o=order(p.orderId),f=item(p.itemId),qty=o.quantity,food=orderTarget(o,'food'),freight=orderTarget(o,'delivery'),foodSupport=orderSum(o,'food','Confirmed'),freightSupport=orderSum(o,'delivery','Confirmed');return {qty,food,freight,foodSupport,freightSupport,total:food+freight,remaining:Math.max(0,food+freight-foodSupport-freightSupport),pending:orderSum(o,'food','Pending')+orderSum(o,'delivery','Pending'),perPallet:round((food+freight-foodSupport-freightSupport)/qty),saving:Math.max(0,qty*p.individualFreight-freight),f,o};}
function joinPool(id,bank,quantity){if(state.role==='bank'&&bank!==state.bank)throw Error('Join for your selected food bank.');const p=poolBy(id),f=item(p?.itemId),o=order(p?.orderId),receiver=partnerNamed(bank);quantity=xint(quantity);if(!p||p.status!=='Open'||!orderOpen(o))throw Error('This shared purchase is not open.');if(receiver?.status!=='Reviewed')throw Error('Complete the food bank review before joining.');if(!receiver.temperatures.includes(f.temp)||quantity>receiver.pallets)throw Error('Receiving capacity or temperature is not compatible.');if(quantity>Math.min(o.quantity-poolQuantity(p),f.pallets-held(f)))throw Error('That quantity is no longer available.');const j={id:uid('J-'),bank,quantity};p.joins.push(j);f.allocations.push({id:j.id,bank,pallets:quantity,status:'Requested',poolId:p.id});auditExchange('Joined shared purchase',p.id,bank+' · '+quantity+' pallets');return j;}
function confirmPool(id){requireOps();const p=poolBy(id),f=item(p?.itemId);if(!p||p.status!=='Open'||!openFood(f))throw Error('This purchase is unavailable.');const o=order(p.orderId);if(poolQuantity(p)!==o.quantity)throw Error('Fill all pallet positions before confirming the shared purchase.');if(partnerNamed(o.supplier)?.status!=='Reviewed')throw Error('Review the supplier first.');for(const j of p.joins){if(partnerNamed(j.bank)?.status!=='Reviewed')throw Error('Review every recipient first.');const a=f.allocations.find(a=>a.id===j.id);if(!a||a.status!=='Requested'&&a.status!=='Confirmed')throw Error('A recipient allocation needs review.');}p.joins.forEach(j=>f.allocations.find(a=>a.id===j.id).status='Confirmed');p.supplierAccepted=true;p.status='Confirmed';auditExchange('Supplier and recipients confirmed',p.id,'Demo quote and allocation approval recorded.');}
function createPoolShipment(id){requireOps();const p=poolBy(id),o=order(p?.orderId),f=item(p?.itemId);if(p?.shipmentId)return ship(p.shipmentId);if(!p?.supplierAccepted||p.status!=='Confirmed')throw Error('Confirm supplier and recipient allocations first.');const s={id:uid('D-'),itemId:f.id,orderFundingId:o.id,poolId:p.id,exchangeControlled:true,title:'Shared purchase · '+f.product,origin:f.city,dest:[...new Set(p.joins.map(j=>partnerNamed(j.bank).city))].join(' · '),route:[f.city,...new Set(p.joins.map(j=>partnerNamed(j.bank).city))],date:f.deadline,pallets:o.quantity,pounds:Math.round(f.pounds*o.quantity/f.pallets),temp:f.temp,status:'Planning',linehaul:o.deliveryTarget,handling:0,fee:0,carrier:'',validated:false,review:'',pledges:[],events:['Shared purchase approved; carrier offers requested']};state.shipments.unshift(s);p.shipmentId=s.id;o.deliveryShipmentId=s.id;auditExchange('Transportation requested',s.id,p.id);return s;}
function sharedPage(){return head('','Pool the purchase. Share the freight.','See the full delivered cost, join other food banks, and fund the remaining need.',btn('Start a shared purchase','x-pool-new','primary'))+`<div class="exchange-grid">${ex().pools.map(p=>{const c=poolCosts(p);return `<article class="card x-card"><div class="section-head"><span class="small muted">${p.id}</span>${badge(p.status,p.status==='Confirmed'?'teal':'blue')}</div><h3>${esc(c.f.product)}</h3><p>${esc(c.o.supplier)} · ${esc(c.f.city)}</p><div class="x-price"><strong>${money(c.perPallet)}</strong><span>remaining per pallet at the full shared quantity</span></div><div class="x-costlines"><span>Food purchase</span><b>${money(c.food)}</b><span>Transportation estimate</span><b>${money(c.freight)}</b><span>Confirmed support</span><b>−${money(c.foodSupport+c.freightSupport)}</b><span>Recipient balance</span><b>${money(c.remaining)}</b></div><div class="progress"><span style="width:${poolQuantity(p)/c.qty*100}%"></span></div><p class="small">${poolQuantity(p)} / ${c.qty} pallets joined · ${c.qty-poolQuantity(p)} open</p><p class="small muted">${money(c.pending)} pledged but unconfirmed. Illustrative freight saving: ${money(c.saving)} versus ${money(p.individualFreight)} per pallet separately.</p><div class="row wrap">${btn('Cost & participants','x-pool','primary',p.id)}${btn('Fund this order','order-detail','',p.orderId)}</div></article>`;}).join('')}</div><div class="note">All prices are illustrative. Join requests hold inventory pending supplier confirmation. Shared freight is apportioned by pallet count; final routing and payment terms require review.</div>`;}
function poolDialog(id){const p=poolBy(id),c=poolCosts(p);dialog(c.f.product,`<div class="x-price"><strong>${money(c.remaining)}</strong><span>remaining total · ${money(c.perPallet)} / pallet</span></div><div class="x-costlines"><span>Food</span><b>${money(c.food)}</b><span>Freight</span><b>${money(c.freight)}</b><span>Confirmed support</span><b>−${money(c.foodSupport+c.freightSupport)}</b><span>Pending support (not deducted)</span><b>${money(c.pending)}</b></div><h3>Participants</h3>${p.joins.map(j=>`<div class="allocation"><div><strong>${esc(j.bank)}</strong><small>${j.quantity} pallets · ${money(round(c.remaining*j.quantity/c.qty))} estimated remaining share</small></div>${badge(item(p.itemId).allocations.find(a=>a.id===j.id)?.status||'Review','gray')}</div>`).join('')}<div class="note">Pallet-share figures are estimates; rounding may leave cents to reconcile. Buyer balances need payment approval before dispatch.</div>${p.status==='Open'&&poolQuantity(p)<c.qty?xform('join',select('bank','Joining food bank',ex().partners.filter(p=>p.kind==='Food bank').map(p=>p.name),state.bank)+field('quantity','Pallets to join','number',1,`required min="1" max="${c.qty-poolQuantity(p)}" step="1"`)+`<label class="check"><input type="checkbox" required> I reviewed the estimated delivered cost and receiving requirements.</label>`,id,'Join shared purchase'):''}<hr class="rule"><div class="row wrap">${btn('Fund the order','order-detail','primary',p.orderId)}${ops()&&p.status==='Open'?btn('Confirm supplier & recipients','x-pool-confirm','',id):''}${ops()&&p.status==='Confirmed'&&!p.shipmentId?btn('Request transportation','x-pool-ship','',id):''}${p.shipmentId?btn('View delivery','ship','',p.shipmentId):''}${ops()&&p.status==='Confirmed'?btn('Record buyer balances','x-buyer-balance','',id):''}</div>`,p.id+' · DELIVERED COST',true);}
function recordBuyerBalances(id){requireOps();const p=poolBy(id),o=order(p?.orderId);if(p?.status!=='Confirmed')throw Error('Confirm the shared purchase first.');if(orderSum(o,'food','Pending')+orderSum(o,'delivery','Pending')>0)throw Error('Confirm or release pending sponsorships before recording buyer balances.');const food=orderGap(o,'food'),delivery=orderGap(o,'delivery');if(!food&&!delivery)throw Error('This order is already covered.');o.pledges.push({id:uid('BP-'),sponsor:'Participating food banks',food,delivery,status:'Confirmed',sourceBuyer:true});auditExchange('Buyer balances confirmed',p.id,`Food ${money(food)} · freight ${money(delivery)}. Demo only; no payment collected.`);}
function startPool(v){const f=item(v.itemId);if(!f||!['For sale','Shared order'].includes(f.type)||!openFood(f))throw Error('Choose an open purchase listing.');if(ex().pools.some(p=>p.itemId===f.id))throw Error('This listing already has a shared purchase.');const quantity=xint(v.quantity);if(quantity>f.pallets-held(f))throw Error('Not enough unreserved inventory.');let o=state.orders.find(o=>o.itemId===f.id&&o.status!=='Canceled');if(o)throw Error('This listing already has a funding campaign; review that campaign first.');o=createPurchaseOrder({title:'Shared purchase · '+f.product,buyer:state.bank,buyerType:'Food bank',supplier:f.org,quantity,unit:'pallets',unitPrice:f.price,deliveryTarget:xnumber(v.freight),deadline:f.deadline,itemId:f.id,notes:'Pooled food bank purchase. Supplier and recipients must approve.'});const p={id:uid('POOL-'),itemId:f.id,orderId:o.id,joins:[],individualFreight:xnumber(v.individual),status:'Open',supplierAccepted:false};ex().pools.push(p);auditExchange('Shared purchase created',p.id,f.product);return p;}
function deliveredCostDialog(fid){const p=ex().pools.find(p=>p.itemId===fid);if(p){poolDialog(p.id);return;}const f=item(fid),s=state.shipments.find(s=>s.itemId===fid&&s.status!=='Canceled');dialog('Compare delivered cost',`<h3>${esc(f.product)}</h3><div class="details">${detail('Food price',f.price?money(f.price)+' / pallet':'Donated food')}${detail('Available',Math.max(0,f.pallets-held(f))+' pallets')}${detail('Freight estimate',s?money(target(s)):'Quote needed')}${detail('Confirmed freight support',s?money(confirmed(s)):'Not yet quoted')}</div><div class="note">Delivered cost = food + transportation − confirmed support. A free food offer can still have a transportation cost.</div><div class="row wrap">${btn('View listing','food','primary',fid)}${f.price?btn('Start a shared purchase','x-pool-new','',fid):''}${s?btn('View transportation quote','ship','',s.id):''}</div>`,'DELIVERED COST');}
function addCarrierBid(v){const s=ship(v.shipmentId),p=partnerBy(v.partnerId);if(!s||s.status!=='Planning')throw Error('Choose a shipment awaiting capacity.');if(p?.kind!=='Carrier')throw Error('Choose a carrier.');const b={id:uid('B-'),shipmentId:s.id,partnerId:p.id,amount:v.kind==='Donated transportation'?0:round(xnumber(v.amount,0.01)),pallets:xint(v.pallets),pounds:xnumber(v.pounds,1),temp:v.temp,expires:xtext(v.expires),window:xtext(v.window,80),kind:v.kind,status:'Offered',notes:String(v.notes||'').slice(0,1000)};if(b.expires<s.date)throw Error('The quote must remain valid through pickup.');if(b.pallets<s.pallets||b.pounds<s.pounds||b.temp!==s.temp)throw Error('Capacity, weight, and temperature must match this shipment.');ex().bids.push(b);auditExchange('Carrier offer received',s.id,p.name+' · '+money(b.amount));return b;}
function acceptCarrierBid(id){requireOps();const b=ex().bids.find(b=>b.id===id),s=ship(b?.shipmentId),p=partnerBy(b?.partnerId);if(!b||b.status!=='Offered'||s?.status!=='Planning')throw Error('This offer is no longer available.');if(p?.status!=='Reviewed')throw Error('Complete the carrier review first.');if(!p.temperatures.includes(s.temp)||b.pallets<s.pallets||b.pounds<s.pounds||b.expires<s.date)throw Error('Carrier capability or offer validity needs review.');const changed=s.linehaul!==b.amount;s.linehaul=b.amount;s.carrier=p.name;s.carrierPartnerId=p.id;s.carrierBidId=b.id;s.validated=false;s.exchangeControlled=true;if(changed&&(confirmed(s)+pending(s)>0))s.review='Transportation price changed. Review sponsor and recipient terms.';ex().bids.filter(x=>x.shipmentId===s.id&&x.status==='Accepted').forEach(x=>x.status='Superseded');b.status='Accepted';s.events.push('Carrier offer accepted · '+p.name);auditExchange('Carrier offer accepted',s.id,p.name+' · '+money(b.amount));return s;}
function carrierPage(){const active=state.shipments.filter(s=>s.status==='Planning');return head('','Carrier marketplace','Quote a lane, offer a return trip, or donate transportation. BHD reviews the award.',btn('Post available capacity','x-capacity','primary'))+`<div class="exchange-grid">${active.map(s=>`<article class="card x-card"><div class="section-head"><span class="small muted">${s.id}</span>${badge(s.carrier?'Capacity assigned':'Open for offers',s.carrier?'teal':'amber')}</div><h3>${esc(s.title)}</h3><p>${esc(s.origin)} → ${esc(s.dest)}</p><div class="x-facts"><span>${s.pallets} pallets</span><span>${num(s.pounds)} lb</span><span>${s.temp}</span><span>${date(s.date)}</span></div><div class="x-costlines"><span>Current transportation total</span><b>${money(target(s))}</b><span>Confirmed funding</span><b>${money(confirmed(s))}</b><span>Carrier offers</span><b>${ex().bids.filter(b=>b.shipmentId===s.id&&['Offered','Accepted'].includes(b.status)).length}</b></div><div class="row wrap">${btn('Quote / donate this lane','x-bid','primary',s.id)}${btn('Compare offers','x-bids','',s.id)}</div></article>`).join('')}</div><h2 class="sec-h">Available capacity & return trips</h2><div class="exchange-grid">${ex().capacity.map(c=>`<article class="card x-card">${badge(c.kind,'blue')}<h3>${esc(partnerBy(c.partnerId)?.name)}</h3><p>${esc(c.origin)} → ${esc(c.destination)}</p><div class="x-facts"><span>${c.pallets} pallets</span><span>${num(c.pounds)} lb</span><span>${c.temp}</span><span>${date(c.date)}</span></div><p>${esc(c.notes)}</p><small class="muted">${active.filter(s=>s.origin===c.origin&&s.temp===c.temp&&s.date===c.date&&s.pallets<=c.pallets&&s.pounds<=c.pounds).length} possible pickup matches; destination and appointments need review.</small></article>`).join('')}</div>`;}
function carrierSelect(){return '<div class="field"><label for="carrier-choice">Carrier</label><select class="input" name="partnerId" id="carrier-choice">'+ex().partners.filter(p=>p.kind==='Carrier').map(p=>'<option value="'+p.id+'">'+esc(p.name)+'</option>').join('')+'</select></div>';}
function bidDialog(sid){const s=ship(sid);dialog('Offer capacity for this lane',xform('bid',`<p>${esc(s.origin)} → ${esc(s.dest)} · ${s.pallets} pallets · ${s.temp}</p><input type="hidden" name="shipmentId" value="${sid}"><div class="form-grid">${carrierSelect()}${select('kind','Offer type',['Paid quote','Donated transportation'])}${field('amount','Transportation quote ($)','number',s.linehaul,'min="0" step="0.01" required')}${field('pallets','Pallet capacity','number',26,'min="1" step="1" required')}${field('pounds','Weight capacity (lb)','number',40000,'min="1" required')}${select('temp','Equipment temperature',['Ambient','Refrigerated','Frozen'],s.temp)}${field('expires','Valid through pickup','date',s.date,'required')}${field('window','Pickup window','text','08:00-15:00','required')}${area('notes','Stops, equipment and conditions')}</div><p class="small muted">Donated transportation uses $0; handling and coordination may remain.</p>`,'','Submit demo offer'),'CARRIER OFFER',true);}
function bidsDialog(sid){const s=ship(sid),offers=ex().bids.filter(b=>b.shipmentId===sid);dialog('Compare carrier offers',`<h3>${esc(s.title)}</h3>${offers.map(b=>`<section class="x-offer">${demoReview(partnerBy(b.partnerId))}<h3>${esc(partnerBy(b.partnerId)?.name)}</h3><div class="x-price"><strong>${money(b.amount+s.handling+s.fee)}</strong><span>transportation ${money(b.amount)} + handling ${money(s.handling)} + BHD ${money(s.fee)}</span></div><p>${esc(b.kind)} · ${b.temp} · ${b.pallets} pallets · ${num(b.pounds)} lb</p><p>${esc(b.notes)}</p>${badge(b.status,'gray')}${ops()&&b.status==='Offered'?btn('Accept offer','x-bid-accept','primary',b.id):''}</section>`).join('')||'<div class="empty">No offers yet.</div>'}<div class="note">Accepting a demo offer does not dispatch a truck. Review the revised price, capacity, documents and receiving appointments.</div>`,sid,true);}
function addCapacity(v){if(partnerBy(v.partnerId)?.kind!=='Carrier')throw Error('Choose a carrier.');if(v.date<demoDate)throw Error('Choose an upcoming date.');const c={id:uid('C-'),partnerId:v.partnerId,origin:v.origin,destination:v.destination,pallets:xint(v.pallets),pounds:xnumber(v.pounds,1),temp:v.temp,date:v.date,kind:v.kind,notes:String(v.notes||'').slice(0,1000)};ex().capacity.unshift(c);auditExchange('Capacity posted',c.id,partnerBy(c.partnerId).name);return c;}
function capacityDialog(){dialog('Post available capacity',xform('capacity',`<div class="form-grid">${carrierSelect()}${select('kind','Capacity type',['Return trip','Spare capacity','Donated capacity'])}${select('origin','Pickup area',Object.keys(exchangeCities))}${select('destination','Destination area',Object.keys(exchangeCities),'Columbus, OH')}${field('pallets','Pallet spaces','number',10,'required min="1" step="1"')}${field('pounds','Weight capacity (lb)','number',15000,'required min="1"')}${select('temp','Temperature',['Ambient','Refrigerated','Frozen'])}${field('date','Available date','date','2026-10-29','required')}${area('notes','Route and appointment details')}</div>`,'','Post capacity'),'CARRIER NETWORK',true);}
function releaseShipmentFunding(s){activePledges(s).forEach(p=>p.status='Released');const o=order(s.orderFundingId);if(o)for(const p of o.pledges){if(['Confirmed','Pending'].includes(p.status)&&p.delivery>0){p.releasedDelivery=(p.releasedDelivery||0)+p.delivery;p.delivery=0;if(!p.food)p.status='Released';}}reconcileAllocations();}
function generalDonationAvailable(id){const p=state.generalDonations.find(p=>p.id===id);return p?.status==='Confirmed'?round(p.amount-ex().allocations.filter(a=>a.donationId===id&&a.status==='Applied').reduce((n,a)=>n+a.amount,0)):0;}
function generalAvailable(){reconcileAllocations();return round(state.generalDonations.reduce((n,p)=>n+generalDonationAvailable(p.id),0));}
function reconcileAllocations(){for(const pool of ex().pools){if(order(pool.orderId)?.status==='Canceled'&&pool.status!=='Canceled'){pool.status='Canceled';for(const a of item(pool.itemId)?.allocations||[])if(a.poolId===pool.id)a.status='Declined';}}for(const a of ex().allocations){if(a.status!=='Applied')continue;const t=a.targetType==='order'?order(a.targetId):ship(a.targetId),p=t?.pledges.find(p=>p.id===a.pledgeId);if(!t||t.status==='Canceled'||!p||p.status==='Released'||(a.targetType==='order'&&a.purpose==='delivery'&&t.deliveryShipmentId&&ship(t.deliveryShipmentId)?.status==='Canceled')||(a.targetType==='order'&&p[a.purpose]<a.amount)){a.status='Returned';if(p)p.status='Released';}}}
function allocateGeneral(v){requireOps();reconcileAllocations();if(!ex().fund.recipient)throw Error('Set the demo fund recipient and allocation policy first.');const reason=xtext(v.reason,500),donation=state.generalDonations.find(p=>p.id===v.donationId),amount=round(xnumber(v.amount,0.01));if(donation?.status!=='Confirmed'||amount>generalDonationAvailable(donation.id))throw Error('Insufficient confirmed, unallocated support.');const t=v.targetType==='order'?order(v.targetId):v.targetType==='shipment'?ship(v.targetId):null,purpose=v.targetType==='shipment'?'delivery':v.purpose;if(!['food','delivery'].includes(purpose))throw Error('Choose food or transportation.');if(!t||(v.targetType==='order'?!orderOpen(t):t.status!=='Planning'||!!t.review))throw Error('Choose an open campaign without a review hold.');const gap=v.targetType==='order'?orderGap(t,purpose):available(t);if(amount>gap)throw Error('This allocation exceeds the remaining campaign gap.');const id=uid('GA-'),pledge={id:uid('GP-'),sponsor:donation.sponsor,status:'Confirmed',sourceGeneral:id,kind:'General fund allocation'};if(v.targetType==='order'){pledge.food=purpose==='food'?amount:0;pledge.delivery=purpose==='delivery'?amount:0;}else pledge.amount=amount;t.pledges.push(pledge);const a={id,donationId:donation.id,targetType:v.targetType,targetId:t.id,purpose,amount,pledgeId:pledge.id,status:'Applied',reason,date:demoDate,approvedBy:ex().fund.approver};ex().allocations.push(a);auditExchange('General donation allocated',t.id,donation.sponsor+' · '+money(amount)+' · '+purpose);return a;}
function returnAllocation(id){requireOps();const a=ex().allocations.find(a=>a.id===id),t=a?.targetType==='order'?order(a?.targetId):ship(a?.targetId);if(!a||a.status!=='Applied')throw Error('This allocation is not active.');if(t?.status==='Delivered'||t?.status==='In transit'||t?.deliveryShipmentId&&['Delivered','In transit'].includes(ship(t.deliveryShipmentId)?.status))throw Error('Funding is committed to a shipment already released.');t.pledges.find(p=>p.id===a.pledgeId).status='Released';a.status='Returned';auditExchange('Allocation returned',a.targetId,money(a.amount)+' available to reallocate.');}
function allocationPanel(){return `<section class="fund-allocation"><div class="section-head"><div><h2>Where general donations go</h2><p class="small muted">${ex().fund.recipient?'Demo fund recipient: '+esc(ex().fund.recipient):'Fund recipient not selected'} · Approver: ${esc(ex().fund.approver)}</p></div><div class="row wrap">${ops()?btn('Fund settings','x-fund-settings','')+btn('Allocate general support','x-allocate','primary'):''}</div></div><p class="small muted">${esc(ex().fund.policy)}. Allocations are ledger entries in this demo, not payments.</p><div class="card table-wrap"><table><thead><tr><th>Original donor</th><th>Destination</th><th>Amount / purpose</th><th>Approval & status</th><th></th></tr></thead><tbody>${ex().allocations.map(a=>`<tr><td>${esc(state.generalDonations.find(p=>p.id===a.donationId)?.sponsor)}<small>${esc(a.donationId)}</small></td><td>${esc(a.targetId)}<small>${esc(a.reason)}</small></td><td>${money(a.amount)}<small>${a.purpose==='food'?'Food purchase':'Transportation'}</small></td><td>${badge(a.status,a.status==='Applied'?'teal':'gray')}<small>${esc(a.approvedBy)} · ${date(a.date)}</small></td><td>${btn('View destination',a.targetType==='order'?'order-detail':'ship','sm',a.targetId)}${ops()&&a.status==='Applied'?btn('Return to fund','x-allocation-return','sm',a.id):''}</td></tr>`).join('')}</tbody></table>${ex().allocations.length?'':'<div class="empty">Every allocation will appear here with its donor, destination and approval.</div>'}</div></section>`;}
function allocateDialog(){const donors=state.generalDonations.filter(p=>generalDonationAvailable(p.id)>0);if(!donors.length){toast('Confirm a general donation before allocating it.');return;}const targets=[...state.orders.filter(orderOpen).map(o=>['order|'+o.id,o.title]),...state.shipments.filter(s=>s.status==='Planning'&&!s.orderFundingId&&!s.review).map(s=>['shipment|'+s.id,s.title])];dialog('Allocate general support',xform('allocate',`<div class="field"><label for="allocation-donor">Original donation</label><select id="allocation-donor" class="input" name="donationId">${donors.map(p=>`<option value="${p.id}">${esc(p.sponsor)} · ${money(generalDonationAvailable(p.id))} available</option>`).join('')}</select></div><div class="field"><label for="allocation-target">Destination</label><select id="allocation-target" class="input" name="target">${targets.map(([id,title])=>`<option value="${id}">${esc(title)} · ${id.split('|')[1]}</option>`).join('')}</select></div>${select('purpose','Purpose',['food','delivery'])}${field('amount','Allocation amount ($)','number',100,'required min="0.01" step="0.01"')}${area('reason','Reason / need addressed')}<label class="check"><input type="checkbox" required> I reviewed the recipient, purpose, available balance and remaining campaign need.</label><p class="small muted">Shipment allocations always cover transportation. The original donation keeps its leaderboard credit; allocation never creates a second donation.</p>`,'','Approve demo allocation'),'GENERAL FUND',true);}
function networkPage(){return xtabs('network',networkView,[['partners','Partner directory'],['documents','Documents'],['audit','Activity trail']])+(networkView==='documents'?documentPage():networkView==='audit'?auditPage():partnerPage());}
function partnerPage(){return head('','A network you can work with.','Review organizations, receiving capabilities and documents before coordinating a move.',btn('Register an organization','x-partner-new','primary'))+`<div class="note blue">Demo onboarding only. “Reviewed” means the sample checklist is complete; it is not an external credential check or a secure account. No invitations or verification messages are sent.</div><div class="exchange-grid three">${ex().partners.map(p=>`<article class="card x-card"><div class="section-head"><span class="small muted">${esc(p.kind)}</span>${demoReview(p)}</div><h3>${esc(p.name)}</h3><p>${esc(p.city)} · ${esc(p.contact)}</p><div class="x-facts">${p.temperatures.map(t=>`<span>${t}</span>`).join('')}<span>${p.pallets} pallet capacity</span></div><p class="small muted">Receiving / availability: ${esc(p.hours)}<br>${ex().documents.filter(d=>d.parentType==='partner'&&d.parentId===p.id).length} documents attached</p><div class="row wrap">${btn('Profile & review','x-partner','primary',p.id)}${btn('Upload document','x-doc','',`partner|${p.id}`)}</div></article>`).join('')}</div>`;}
function partnerDialog(id=''){const p=partnerBy(id);dialog(p?'Organization profile':'Register an organization',xform('partner',`<div class="form-grid">${field('name','Organization name','text',p?.name||'','required maxlength="100"')}${select('kind','Organization type',['Food bank','Supplier','Carrier'],p?.kind||'Food bank')}${select('city','Operating city',Object.keys(exchangeCities),p?.city)}${field('contact','Contact / coordinator','text',p?.contact||'','required maxlength="100"')}${field('pallets','Pallet capacity','number',p?.pallets||10,'required min="1" step="1"')}${field('hours','Receiving / availability hours','text',p?.hours||'08:00-15:00','required')}</div><div class="purpose-choices">${['Ambient','Refrigerated','Frozen'].map(t=>`<label><input type="checkbox" name="temperatures" value="${t}" ${(p?.temperatures||['Ambient']).includes(t)?'checked':''}>${t}</label>`).join('')}</div><div class="note">Changes to capability or identity return this organization to review. Use fictional details in the prototype.</div>`,id,'Save organization')+(p?`<hr class="rule"><h3>Review record</h3>${demoReview(p)}<p>${esc(p.reviewNote||'No review completed yet.')}</p><p class="small muted">${esc(p.reviewer||'Reviewer not assigned')}</p><div class="row wrap">${btn('Upload document','x-doc','',`partner|${id}`)}${ops()?btn('Review organization','x-review','primary',id):''}</div>`:''),'PARTICIPANT ONBOARDING',true);}
function savePartner(v){const old=partnerBy(v.id),name=xtext(v.name,100),contact=xtext(v.contact,100),hours=xtext(v.hours,80),pallets=xint(v.pallets),temperatures=v.temperatures;if(!['Food bank','Supplier','Carrier'].includes(v.kind)||!exchangeCities[v.city]||!temperatures.length||temperatures.some(t=>!['Ambient','Refrigerated','Frozen'].includes(t)))throw Error('Choose a valid organization type, city and temperature capability.');if(old&&!ops())throw Error('Operations manages existing organization profiles.');if(old&&name!==old.name)throw Error('Keep the existing organization name to preserve linked records.');if(!old&&ex().partners.some(p=>p.name.toLowerCase()===name.toLowerCase()))throw Error('This organization already exists.');const p=old||{id:uid('P-')};Object.assign(p,{name,kind:v.kind,city:v.city,contact,hours,pallets,temperatures,status:'Pending',checks:[],reviewer:'',reviewNote:''});if(!old)ex().partners.push(p);if(p.kind==='Food bank'){state.profiles[p.name]={hours,temp:temperatures.join(', '),pallets,needs:''};}auditExchange('Organization submitted',p.id,name);return p;}
function reviewPartner(id,checks,note){requireOps();const p=partnerBy(id);if(!p)throw Error('Organization unavailable.');if(['identity','authority','capability','documents'].some(c=>!checks.includes(c)))throw Error('Complete every review check.');if(!ex().documents.some(d=>d.parentType==='partner'&&d.parentId===id))throw Error('Attach a review document first.');const reviewNote=xtext(note);Object.assign(p,{status:'Reviewed',checks,reviewer:'BHD Operations · demo',reviewNote});auditExchange('Organization reviewed',id,p.name+' · simulated verification');}
function reviewDialog(id){requireOps();const p=partnerBy(id);dialog('Review '+esc(p.name),xform('review',`<p>Confirm the records and capability for this ${esc(p.kind.toLowerCase())}. This records a simulated review only.</p>${[['identity','Organization and contact identity reviewed'],['authority',p.kind==='Carrier'?'Carrier authority and insurance reviewed':'Authorized representative / receiving eligibility reviewed'],['capability','Storage, equipment, capacity and hours reviewed'],['documents','Supporting documents reviewed']].map(([v,l])=>`<label class="check"><input type="checkbox" name="checks" value="${v}" required>${l}</label>`).join('')}${area('note','Review note / evidence references')}`,id,'Complete demo review'),'ORGANIZATION REVIEW',true);}
function documentPage(){return head('','Documents & handoff evidence','Keep organization records, bills of lading, lot details and delivery evidence tied to the work.')+`<div class="note">Uploads stay in this browser. Supported: PDF, PNG, JPEG, WebP, and plain text, up to 500 KB each and 2 MB total. Use demonstration documents.</div><div class="card table-wrap"><table><thead><tr><th>Document</th><th>Linked record</th><th>Type</th><th>Added</th><th></th></tr></thead><tbody>${ex().documents.map(d=>`<tr><td><strong>${esc(d.name)}</strong><small>${Math.ceil(d.size/1024)} KB</small></td><td>${esc(d.parentId)}<small>${d.parentType}</small></td><td>${esc(d.kind)}</td><td>${date(d.date)}</td><td>${btn('Open document','x-doc-open','sm',d.id)}</td></tr>`).join('')}</tbody></table>${ex().documents.length?'':'<div class="empty">Upload a document from an organization profile or a delivery record.</div>'}</div>`;}
function uploadDialog(parentType,parentId){dialog('Attach a document',xform('document',`<input type="hidden" name="parentType" value="${esc(parentType)}"><input type="hidden" name="parentId" value="${esc(parentId)}">${select('kind','Document type',parentType==='partner'?['Organization record','Insurance / authority','Receiving capabilities']:['Bill of lading','Pickup evidence','Proof of delivery','Supplier invoice'])}${field('file','Document file','file','','required accept="application/pdf,image/png,image/jpeg,image/webp,text/plain"')}<p class="small muted">Local demo attachment, maximum 500 KB. Keep real sensitive documents out of this prototype.</p>`,'','Attach document'),parentId,true);}
async function readDemoDocument(file){if(!file?.size)throw Error('Choose a document.');if(!['application/pdf','image/png','image/jpeg','image/webp','text/plain'].includes(file.type)||file.size>512000)throw Error('Use a supported document under 500 KB.');if(ex().documents.reduce((n,d)=>n+d.size,0)+file.size>2097152)throw Error('This demo has reached its 2 MB document limit.');return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve({data:r.result,name:file.name,size:file.size,mime:file.type});r.onerror=()=>reject(Error('Could not read document.'));r.readAsDataURL(file);});}
function auditPage(){return head('','Activity trail','Follow decisions, approvals, funding allocations and custody events.')+`<div class="card table-wrap"><table><thead><tr><th>Action</th><th>Record</th><th>Detail</th><th>By / time</th></tr></thead><tbody>${ex().audit.map(a=>`<tr><td><strong>${esc(a.action)}</strong></td><td>${esc(a.reference)}</td><td>${esc(a.detail)}</td><td>${esc(a.actor)}<small>${stamp(a.time)}</small></td></tr>`).join('')}</tbody></table>${ex().audit.length?'':'<div class="empty">Network actions will be recorded here.</div>'}</div>`;}
function shipmentEvidence(s){return ex().documents.filter(d=>d.parentType==='shipment'&&d.parentId===s.id);}
function canDispatch(s){if(!basicCanDispatch(s)&&!(s.status==='Planning'&&!s.review&&s.carrier&&s.validated&&target(s)===0&&s.carrierBidId&&(!s.itemId||accepted(item(s.itemId))===s.pallets)))return false;if(!s.exchangeControlled)return true;const p=partnerBy(s.carrierPartnerId);return (!s.recurringPlanId||s.sourceConfirmed)&&(!s.itemId||openFood(item(s.itemId)))&&p?.status==='Reviewed'&&p.name===s.carrier&&!!s.lot&&shipmentEvidence(s).some(d=>d.kind==='Bill of lading')&&(!s.orderFundingId||(order(s.orderFundingId)?.status!=='Canceled'&&orderSum(order(s.orderFundingId),'food','Confirmed')>=orderTarget(order(s.orderFundingId),'food')));}
function custodyPanel(s){const pickup=ex().handoffs.find(h=>h.shipmentId===s.id&&h.kind==='Pickup'),docs=shipmentEvidence(s);return `<div class="custody-panel"><div class="section-head"><h3>Custody & evidence</h3>${s.exchangeControlled?badge('Reviewed workflow','blue'):badge('Legacy demo delivery','gray')}</div><div class="custody-steps"><span class="done">Planned</span><span class="${s.carrier?'done':''}">Carrier assigned</span><span class="${pickup?'done':''}">Picked up</span><span class="${s.status==='Delivered'?'done':''}">Received</span></div><p class="small muted">Lot / product reference: ${esc(s.lot||'Not recorded')} · ${docs.length} documents<br>Operations owner: BHD Operations</p>${s.orderFundingId?`<div class="note">Food purchase and transportation funding are linked to ${s.orderFundingId}. Confirmed transportation support shown here includes that campaign; it is counted once.</div>`:''}${pickup?`<div class="note">Pickup signed by ${esc(pickup.signer)} · ${esc(pickup.lot)} · ${esc(pickup.temperature||'Ambient')} · ${date(pickup.date)}</div>`:''}<div class="row wrap">${s.status==='Planning'?btn('Compare carrier offers','x-bids','',s.id)+btn('Offer capacity','x-bid','',s.id):''}${btn('Upload document','x-doc','',`shipment|${s.id}`)}${ops()&&s.status==='Planning'?btn('Review route & lot','x-route','',s.id):''}${ops()&&s.status==='In transit'&&!pickup?btn('Confirm pickup','x-pickup','primary',s.id):''}${ops()&&s.status==='In transit'&&pickup?btn('Confirm receiving','deliver','primary',s.id):''}</div>${docs.map(d=>`<div class="quote-line"><span>${esc(d.kind)} · ${esc(d.name)}</span>${btn('Open','x-doc-open','sm',d.id)}</div>`).join('')}${s.exchangeControlled&&s.status==='Planning'?'<div class="note">Release requires a reviewed carrier, route approval, lot reference, BOL attachment, accepted recipients and confirmed funding. Shared purchases also require their food balance covered.</div>':''}</div>`;}
function trackingPage(){return head('','Pickup to receipt','Track custody, evidence and exceptions through the delivery.')+`<div class="exchange-grid">${state.shipments.map(s=>`<article class="card x-card"><div class="section-head"><span class="small muted">${s.id}</span>${status(s)}</div><h3>${esc(s.title)}</h3><p>${esc(s.origin)} → ${esc(s.dest)}</p>${custodyPanel(s)}<div class="row wrap">${btn('Full delivery record','ship','primary',s.id)}${s.receipt?btn('View receipt','receipt','',s.id):''}</div></article>`).join('')}</div>`;}
function routeReview(id,v){requireOps();const s=ship(id),lot=xtext(v.lot,100);if(s?.status!=='Planning')throw Error('This shipment is no longer in planning.');if(!s.carrierPartnerId||partnerBy(s.carrierPartnerId)?.status!=='Reviewed')throw Error('Accept an offer from a reviewed carrier first.');if(!v.confirmed)throw Error('Review all route and receiving requirements.');s.lot=lot;s.validated=true;if(s.recurringPlanId)s.sourceConfirmed=true;auditExchange('Route reviewed',id,lot+' · receiving and equipment reviewed');}
function recordPickup(id,v){requireOps();const s=ship(id);if(s?.status!=='In transit'||s.review)throw Error('Release the delivery and resolve any review hold first.');if(ex().handoffs.some(h=>h.shipmentId===id&&h.kind==='Pickup'))throw Error('Pickup is already recorded.');const signer=xtext(v.signer,100),temperature=s.temp==='Ambient'?'Ambient':String(xnumber(v.temperature,-40,100));if(!shipmentEvidence(s).some(d=>d.kind==='Bill of lading'))throw Error('Attach the bill of lading first.');const h={id:uid('H-'),shipmentId:id,kind:'Pickup',signer,temperature,lot:s.lot||xtext(v.lot,100),date:s.date};ex().handoffs.push(h);s.events.push('Pickup confirmed by '+signer);auditExchange('Pickup signed',id,signer+' · lot '+h.lot);return h;}
function recordReceiving(id,v){requireOps();const s=ship(id);if(s?.status!=='In transit'||s.review)throw Error('Shipment must be in transit with review holds resolved.');if(!ex().handoffs.some(h=>h.shipmentId===id&&h.kind==='Pickup'))throw Error('Record pickup before confirming receipt.');const name=xtext(v.name,100),pounds=xnumber(v.pounds,1,s.pounds),receiptDate=xtext(v.date),note=xtext(v.notes,1000),temperature=s.temp==='Ambient'?'Ambient':String(xnumber(v.temperature,-40,100));if(receiptDate<s.date)throw Error('Receipt cannot predate pickup.');if(v.condition==='Issue / hold'){s.review=note;s.events.push('Receiving exception · '+note);auditExchange('Receiving held',id,note);return false;}if(v.condition!=='Accepted'||!v.allStops)throw Error('Confirm accepted condition and all recipient stops.');if(!shipmentEvidence(s).some(d=>d.kind==='Proof of delivery'))throw Error('Attach signed proof of delivery first.');s.receipt={name,pounds,date:receiptDate,note,temperature,lot:s.lot,bank:s.itemId?item(s.itemId).allocations.filter(a=>a.status==='Confirmed').map(a=>a.bank).join(' / '):s.dest};s.status='Delivered';s.events.push('Receiving signed by '+name+' · '+num(pounds)+' lb');ex().handoffs.push({id:uid('H-'),shipmentId:id,kind:'Receiving',signer:name,temperature,lot:s.lot,date:receiptDate});auditExchange('Delivery completed',id,num(pounds)+' actual lb');return true;}
function pickupDialog(id){const s=ship(id);dialog('Confirm pickup',xform('pickup',field('signer','Pickup signer / driver','text','','required')+field('lot','Lot / product reference','text',s.lot||'','required')+(s.temp!=='Ambient'?field('temperature','Recorded temperature (°F)','number',36,'required step="0.1"'):'')+'<label class="check"><input type="checkbox" required> I reviewed pallet quantity, condition, lot details and the BOL.</label>',id,'Record pickup'),'CHAIN OF CUSTODY',true);}
function receivingDialog(id){const s=ship(id);dialog('Confirm receiving',xform('receiving',field('name','Receiving signer','text','','required')+field('pounds','Actual pounds received','number',s.pounds,`required min="1" max="${s.pounds}"`)+field('date','Receipt date','date',s.date,'required')+(s.temp!=='Ambient'?field('temperature','Recorded temperature (°F)','number',36,'required step="0.1"'):'')+select('condition','Receiving condition',['Accepted','Issue / hold'])+area('notes','Receipt notes / exception detail')+'<label class="check"><input type="checkbox" name="allStops" required> All recipient stops and delivery evidence have been reviewed.</label><p class="small muted">Attach a signed proof of delivery from the delivery record. An issue holds the delivery and does not add completed impact.</p>',id,'Record receiving'),'PROOF OF DELIVERY',true);}
function parseBol(text){const get=key=>{const m=text.match(new RegExp('^'+key+'\\s*:\\s*(.+)$','im'));return m?.[1]?.trim()||'';};return {product:get('Product'),pallets:get('Pallets').replace(/,/g,''),pounds:get('Weight').replace(/[^\d.]/g,''),city:get('Pickup'),temp:get('Temperature'),lot:get('Lot'),org:get('Shipper')};}
function rescueDialog(){dialog('Rescue a rejected load',xform('rescue',`<p class="muted small">Paste labeled BOL text to fill a draft, then review every field. Upload the original document to the resulting listing’s delivery. Image/PDF OCR is not connected.</p>${area('bol','BOL text (optional)')}<button class="btn" type="button" data-action="x-bol-fill">Fill draft from BOL text</button><div class="form-grid">${field('product','Product','text','','required')}${field('org','Shipper / food owner','text','','required')}${select('city','Current pickup city',Object.keys(exchangeCities))}${field('pallets','Pallets','number',1,'required min="1" step="1"')}${field('pounds','Weight (lb)','number',1000,'required min="1"')}${select('temp','Temperature',['Ambient','Refrigerated','Frozen'])}${field('deadline','Available through','date',demoDate,'required')}${field('shelf','Shelf life / use-by date','text','','required')}${field('lot','Lot / product reference','text','','required')}${area('reason','Rejection reason and handling requirements')}</div><label class="check"><input type="checkbox" required> The food owner authorized this donation and the food is suitable for recipient review.</label><div class="note">Posting does not approve food safety or transfer ownership. Receivers must review condition, temperature and shelf life.</div>`,'','Post urgent food offer'),'URGENT LOAD RECOVERY',true);}
function createRescue(v){const pallets=xint(v.pallets),pounds=xnumber(v.pounds,1),product=xtext(v.product,100),org=xtext(v.org,100),lot=xtext(v.lot,100),shelf=xtext(v.shelf,100),reason=xtext(v.reason,1000);if(v.deadline<demoDate||!exchangeCities[v.city]||!['Ambient','Refrigerated','Frozen'].includes(v.temp))throw Error('Review pickup location, temperature and deadline.');const f={id:uid('F-'),type:'Donation',title:'Urgent rescue · '+product,product,org,city:v.city,pallets,pounds,temp:v.temp,deadline:v.deadline,shelf,price:0,icon:'truck',band:'gold',status:'Open',notes:reason,lot,allocations:[],comments:[],urgent:true};state.items.unshift(f);auditExchange('Urgent load posted',f.id,product+' · '+org);return f;}
function recurringPickupPage(){return head('','Recurring pickups','Set a repeat route, then confirm food and capacity for each pickup.',btn('Create pickup plan','x-recurring-new','primary'))+`<div class="exchange-grid">${ex().pickupPlans.map(p=>`<article class="card x-card"><div class="section-head">${badge(p.active?'Active plan':'Paused',p.active?'teal':'gray')}<span class="small muted">${p.id}</span></div><h3>${esc(p.supplier)} → ${esc(p.bank)}</h3><p>${esc(p.origin)} → ${esc(p.destination)}</p><div class="x-facts"><span>Every ${p.frequency} days</span><span>Next: ${date(p.nextDate)}</span><span>${p.pallets} pallets</span><span>${p.temp}</span></div><p>Estimated transportation: ${money(p.estimate)} per pickup.</p><div class="row wrap">${ops()&&p.active?btn('Create next pickup draft','x-recurring-draft','primary',p.id):''}${ops()?btn(p.active?'Pause':'Resume','x-recurring-toggle','',p.id):''}</div></article>`).join('')}</div><div class="note">Plans do not book trucks or claim future inventory. Each draft needs fresh food confirmation, carrier acceptance, funding, documents and receiving review. No background scheduling runs in this prototype.</div>`;}
function pickupPlanDialog(){dialog('Create recurring pickup plan',xform('pickup-plan',`<div class="form-grid">${select('supplier','Food supplier',ex().partners.filter(p=>p.kind==='Supplier').map(p=>p.name))}${select('bank','Receiving food bank',ex().partners.filter(p=>p.kind==='Food bank').map(p=>p.name),state.bank)}${select('origin','Pickup city',Object.keys(exchangeCities))}${select('destination','Receiving city',Object.keys(exchangeCities),'Dayton, OH')}${field('pallets','Pallets per pickup','number',4,'required min="1" step="1"')}${field('pounds','Weight per pickup (lb)','number',6000,'required min="1"')}${select('temp','Temperature',['Ambient','Refrigerated','Frozen'])}${field('nextDate','First pickup date','date','2026-10-29','required')}${select('frequency','Repeat every (days)',['7','14'])}${field('estimate','Transportation estimate ($)','number',400,'required min="0" step="0.01"')}</div>`,'','Save pickup plan'),'REPEAT ROUTES',true);}
function addPickupPlan(v){const supplier=partnerNamed(v.supplier),bank=partnerNamed(v.bank);if(supplier?.kind!=='Supplier'||bank?.kind!=='Food bank'||!bank.temperatures.includes(v.temp))throw Error('Choose compatible supplier and receiver profiles.');if(v.nextDate<demoDate||![7,14].includes(Number(v.frequency)))throw Error('Choose a valid upcoming schedule.');const p={id:uid('R-'),supplier:v.supplier,bank:v.bank,origin:v.origin,destination:v.destination,pallets:xint(v.pallets),pounds:xnumber(v.pounds,1),temp:v.temp,nextDate:v.nextDate,frequency:Number(v.frequency),estimate:xnumber(v.estimate),active:true};ex().pickupPlans.push(p);auditExchange('Pickup plan created',p.id,p.supplier+' → '+p.bank);return p;}
function draftRecurringPickup(id){requireOps();const p=ex().pickupPlans.find(p=>p.id===id);if(!p?.active)throw Error('This recurring plan is paused.');if(partnerNamed(p.supplier)?.status!=='Reviewed'||partnerNamed(p.bank)?.status!=='Reviewed')throw Error('Review supplier and receiver first.');if(state.shipments.some(s=>s.recurringPlanId===id&&s.date===p.nextDate&&s.status!=='Canceled'))throw Error('A pickup draft already exists for this date.');const s={id:uid('D-'),recurringPlanId:id,exchangeControlled:true,sourceConfirmed:false,supplier:p.supplier,title:'Recurring pickup · '+p.supplier,origin:p.origin,dest:p.destination,route:[p.origin,p.destination],date:p.nextDate,pallets:p.pallets,pounds:p.pounds,temp:p.temp,status:'Planning',linehaul:p.estimate,handling:0,fee:0,carrier:'',validated:false,review:'',pledges:[],events:['Recurring pickup draft created; confirm food availability']};state.shipments.unshift(s);const next=new Date(p.nextDate+'T12:00:00Z');next.setUTCDate(next.getUTCDate()+p.frequency);p.nextDate=next.toISOString().slice(0,10);auditExchange('Recurring pickup drafted',s.id,p.id);return s;}
function networkFundingGap(){return round(state.shipments.filter(s=>!['Delivered','Canceled'].includes(s.status)).reduce((n,s)=>n+available(s),0)+state.orders.filter(orderOpen).reduce((n,o)=>n+orderGap(o,'food')+(o.deliveryShipmentId?0:orderGap(o,'delivery')),0));}
// Extend the existing interface while keeping its original workflows available.
const originalFoodPage=foodPage,originalTransportPage=transportPage,originalHomePage=homePage,originalGeneralPage=generalDonationPage;
foodPage=()=>xtabs('food',foodView,[['listings','Food listings'],['matches','Matches & needs'],['shared','Shared purchases']])+(foodView==='matches'?matchPage():foodView==='shared'?sharedPage():`<div class="exchange-toolbar">${btn('Rescue a rejected load','x-rescue','')}${btn('Find matches','x-navigate','','food|matches')}${btn('Pool a purchase','x-navigate','','food|shared')}</div>`+originalFoodPage());
transportPage=()=>xtabs('transport',logisticsView,[['board','Delivery board'],['carriers','Carrier marketplace'],['tracking','Pickup & receipt'],['recurring','Recurring pickups']])+(logisticsView==='recurring'?recurringPickupPage():logisticsView==='carriers'?carrierPage():logisticsView==='tracking'?trackingPage():originalTransportPage());
homePage=()=>originalHomePage().replace('Food available. Transportation coordinated. <br><em>Delivery funded.</em>','Give food. Fund food.<br><em>Get it there.</em>')+`<section class="exchange-home"><h2 class="sec-h">Put the network to work</h2><div class="exchange-grid three"><article class="card x-card"><h3>${ex().needs.flatMap(needMatches).length} food matches</h3><p>Standing needs matched to nearby, compatible supply.</p>${btn('See matches','x-navigate','primary','food|matches')}</article><article class="card x-card"><h3>${ex().pools.length} shared purchase</h3><p>Combine quantities and compare the delivered cost.</p>${btn('Explore shared purchases','x-navigate','primary','food|shared')}</article><article class="card x-card"><h3>${ex().bids.filter(b=>b.status==='Offered').length} carrier offers</h3><p>Paid capacity, return trips and donated transportation.</p>${btn('Open carrier marketplace','x-navigate','primary','transport|carriers')}</article></div></section>`;
generalDonationPage=()=>originalGeneralPage()+allocationPanel();
const originalFoodDetail=foodDetail,originalShipDetail=shipDetail,originalDeliveryDialog=deliveryDialog,originalReceiptDialog=receiptDialog;
function appendDialog(html){const b=document.querySelector('.dialog-body');if(b)b.insertAdjacentHTML('beforeend',html);}
foodDetail=id=>{originalFoodDetail(id);appendDialog(`<hr class="rule">${btn('Compare delivered cost','x-cost','primary full',id)}`);};
shipDetail=id=>{originalShipDetail(id);appendDialog(custodyPanel(ship(id)));};
deliveryDialog=id=>ship(id)?.exchangeControlled?receivingDialog(id):originalDeliveryDialog(id);
receiptDialog=id=>{originalReceiptDialog(id);const s=ship(id);if(s)appendDialog(`<h3>Custody record</h3>${custodyPanel(s)}`);};
function navigateExchange(value){const [p,v]=value.split('|');if(p==='food')foodView=v;if(p==='transport')logisticsView=v;go(p);}
document.addEventListener('click',e=>{
 const n=e.target.closest('[data-action]');if(!n)return;const a=n.dataset.action,id=n.dataset.id;
 if(!a.startsWith('x-'))return;
 try{
  if(a==='x-navigate')navigateExchange(id);
  if(a==='x-view'){const [kind,v]=id.split('|');if(kind==='food')foodView=v;if(kind==='transport')logisticsView=v;if(kind==='network')networkView=v;render();}
  if(a==='x-need')needDialog();
  if(a==='x-need-toggle'){const v=needBy(id);if(state.role==='bank'&&v.bank!==state.bank)throw Error('Choose your food bank’s need.');v.active=!v.active;save();render();}
  if(a==='x-alerts-read'){ex().alerts.filter(a=>state.role!=='bank'||a.bank===state.bank).forEach(a=>a.read=true);save();render();}
  if(a==='x-cost')deliveredCostDialog(id);
  if(a==='x-pool')poolDialog(id);
  if(a==='x-pool-new'){const fs=state.items.filter(f=>['For sale','Shared order'].includes(f.type)&&openFood(f)&&!ex().pools.some(p=>p.itemId===f.id));dialog('Start a shared purchase',xform('pool',`<div class="field"><label for="pool-item">Food listing</label><select class="input" id="pool-item" name="itemId">${fs.map(f=>`<option value="${f.id}" ${f.id===id?'selected':''}>${esc(f.product)} · ${money(f.price)}/pallet</option>`).join('')}</select></div>${field('quantity','Total pallets to pool','number',3,'required min="1" step="1"')}${field('freight','Shared transportation estimate ($)','number',600,'required min="0" step="0.01"')}${field('individual','Separate freight benchmark per pallet ($)','number',250,'required min="0" step="0.01"')}<p class="small muted">Estimates only; supplier and carrier confirmation are required.</p>`,'','Create shared purchase'),'SHARED BUYING',true);}
  if(a==='x-pool-confirm'){requireOps();dialog('Confirm supplier & recipients',xform('pool-confirm','<label class="check"><input type="checkbox" required> In this demo, the supplier and every participating food bank accepted quantities, product price, receiving requirements and the estimated transportation share.</label>',id,'Confirm shared purchase'),id,true);}
  if(a==='x-pool-ship'){const s=createPoolShipment(id);save();render();shipDetail(s.id);}
  if(a==='x-buyer-balance'){requireOps();dialog('Record buyer balances',xform('buyer-balance','<p>Record the remaining food and transportation balance as confirmed buyer payments. This does not collect money. Buyer payments do not earn donation leaderboard credit.</p><label class="check"><input type="checkbox" required> I reviewed each food bank’s share and simulated payment reconciliation.</label>',id,'Confirm demo buyer payments'),id,true);}
  if(a==='x-bid')bidDialog(id);
  if(a==='x-bids')bidsDialog(id);
  if(a==='x-bid-accept'){const s=acceptCarrierBid(id);save();render();shipDetail(s.id);}
  if(a==='x-capacity')capacityDialog();
  if(a==='x-recurring-new')pickupPlanDialog();
  if(a==='x-recurring-draft'){const s=draftRecurringPickup(id);save();render();shipDetail(s.id);}
  if(a==='x-recurring-toggle'){requireOps();const p=ex().pickupPlans.find(p=>p.id===id);p.active=!p.active;save();render();}
  if(a==='x-partner-new')partnerDialog();
  if(a==='x-partner')partnerDialog(id);
  if(a==='x-review')reviewDialog(id);
  if(a==='x-doc'){const [t,p]=id.split('|');uploadDialog(t,p);}
  if(a==='x-doc-open'){const d=ex().documents.find(d=>d.id===id);dialog('Document',`<h3>${esc(d.name)}</h3><p>${esc(d.kind)} · ${esc(d.parentId)}</p><a class="btn primary" download="${esc(d.name)}" href="${esc(d.data)}">Download document</a>`,'LOCAL DEMO ATTACHMENT');}
  if(a==='x-route'){const s=ship(id);dialog('Review route & lot',xform('route',field('lot','Lot / product reference','text',s.lot||item(s.itemId)?.lot||'','required')+'<label class="check"><input type="checkbox" name="confirmed" required> I confirmed food availability and reviewed carrier capability, weight, temperatures, stop sequence, shelf life, and receiving appointments.</label>',id,'Approve route review'),id,true);}
  if(a==='x-pickup')pickupDialog(id);
  if(a==='x-fund-settings'){requireOps();dialog('General fund settings',xform('fund-settings',field('recipient','Demo fund recipient organization','text',ex().fund.recipient,'required')+field('approver','Allocation approver','text',ex().fund.approver,'required')+area('policy','Permitted uses and allocation policy',ex().fund.policy)+'<div class="note">These settings document the prototype’s decision process. They do not create a bank account, payment processor or charitable status.</div>','','Save fund settings'),'FUND GOVERNANCE',true);}
  if(a==='x-allocate')allocateDialog();
  if(a==='x-allocation-return'){returnAllocation(id);save();render();}
  if(a==='x-rescue')rescueDialog();
  if(a==='x-bol-fill'){const f=n.closest('form'),v=parseBol(f.querySelector('[name="bol"]').value);for(const [k,value] of Object.entries(v)){const field=f.querySelector(`[name="${k}"]`);if(field&&value&&(field.tagName!=='SELECT'||[...field.options].some(o=>o.value===value)))field.value=value;}toast('Draft filled from labeled text. Review every field before posting.');}
 }catch(error){toast(error.message);}
});
document.addEventListener('submit',async e=>{
 const f=e.target;if(!f.dataset.exchangeForm)return;e.preventDefault();const fd=new FormData(f),v=Object.fromEntries(fd),kind=f.dataset.exchangeForm,id=f.dataset.id,button=f.querySelector('[type="submit"]');button.disabled=true;
 try{
  let after=()=>{closeDialog();render();};
  if(kind==='need'){addNeed({...v,partial:fd.has('partial')});foodView='matches';page='food';}
  if(kind==='join'){joinPool(id,v.bank,v.quantity);after=()=>{render();poolDialog(id);};}
  if(kind==='pool'){const p=startPool(v);foodView='shared';page='food';after=()=>{render();poolDialog(p.id);};}
  if(kind==='pool-confirm'){confirmPool(id);after=()=>{render();poolDialog(id);};}
  if(kind==='buyer-balance'){recordBuyerBalances(id);after=()=>{render();poolDialog(id);};}
  if(kind==='bid'){addCarrierBid(v);after=()=>{render();bidsDialog(v.shipmentId);};}
  if(kind==='pickup-plan'){addPickupPlan(v);page='transport';logisticsView='recurring';}
  if(kind==='capacity'){addCapacity(v);logisticsView='carriers';page='transport';}
  if(kind==='partner'){savePartner({...v,id,temperatures:fd.getAll('temperatures')});page='network';networkView='partners';}
  if(kind==='review'){reviewPartner(id,fd.getAll('checks'),v.note);after=()=>{render();partnerDialog(id);};}
  if(kind==='document'){if(!['partner','shipment'].includes(v.parentType)||!(v.parentType==='partner'?partnerBy(v.parentId):ship(v.parentId)))throw Error('Choose a valid linked record.');const file=await readDemoDocument(fd.get('file'));ex().documents.push({id:uid('DOC-'),...file,parentType:v.parentType,parentId:v.parentId,kind:v.kind,date:demoDate});auditExchange('Document attached',v.parentId,file.name);after=()=>{render();v.parentType==='shipment'?shipDetail(v.parentId):partnerDialog(v.parentId);};}
  if(kind==='route'){routeReview(id,{...v,confirmed:fd.has('confirmed')});after=()=>{render();shipDetail(id);};}
  if(kind==='pickup'){recordPickup(id,v);after=()=>{render();shipDetail(id);};}
  if(kind==='receiving'){const completed=recordReceiving(id,{...v,allStops:fd.has('allStops')});after=()=>{render();completed?receiptDialog(id):shipDetail(id);};}
  if(kind==='fund-settings'){requireOps();ex().fund={recipient:xtext(v.recipient,100),approver:xtext(v.approver,100),policy:xtext(v.policy,1000)};auditExchange('Fund policy saved','General fund',ex().fund.recipient);}
  if(kind==='allocate'){const [targetType,targetId]=v.target.split('|');allocateGeneral({...v,targetType,targetId});}
  if(kind==='rescue'){const f=createRescue(v);page='food';foodView='listings';after=()=>{render();foodDetail(f.id);};}
  save();after();toast('Demo record saved.');
 }catch(error){if(document.body.contains(f))f.querySelector('.error').textContent=error.message;else toast(error.message);}
 finally{if(document.body.contains(button))button.disabled=false;}
});
const renderBeforeExchange=render;
render=()=>{ensureExchange(state);reconcileAllocations();scanNeeds();renderBeforeExchange();};
if(window.addEventListener)window.addEventListener('storage',e=>{if(e.key!==storageKey||!e.newValue)return;try{const latest=JSON.parse(e.newValue);if(latest?.version===2){state=latest;ensureExchange(state);closeDialog();render();}}catch{}});
render();
